function GachaponStepDiscountSsrCell:Awake()

end

function GachaponStepDiscountSsrCell:RefreshShow(data, pool, index)
    local curStep = pool.activity.stepNum
    local isGet = curStep > index
    CfUtils.SetActive(self.ImgGet.gameObject,isGet)
    CfUtils.SetActive(self.UIFX_Status.gameObject, curStep == index)

    if self.UIFX_liuguang then
        CfUtils.SetActive(self.UIFX_liuguang.gameObject,not isGet)
    end

    CfUtils.FillText(self.TxtTipsTitle,localize("STEP_num_",{_num_ = index}))

    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(pool.tenConsume.goodsId)
    if isNotNull(goodsVo) then
        CfUtils.FillImage(self.ImgIcon,goodsVo.photoPath)
    end

    CfUtils.FillText(self.TxtNumIcon,data.currentPrice)
    CfUtils.FillText(self.TxtProbability,localize("（_num_%OFF）",{_num_ = data.discount}))
end

function GachaponStepDiscountSsrCell:OnDestroy()
    self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
    self:Delete()
end

return GachaponStepDiscountSsrCell